import zlib
import base64
import itertools

def try_decompress(data_bytes):
    try:
        return zlib.decompress(data_bytes), 'zlib'
    except Exception:
        return None, None

def try_base64_decode(data_bytes):
    try:
        return base64.b64decode(data_bytes), 'base64'
    except Exception:
        return None, None

# Generate all single byte XOR key attempts
def xor_decrypt(data_bytes, key):
    return bytes([b ^ key for b in data_bytes])

